#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_run_next_rejected_when_at_capacity(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_set_max_concurrent(&s, 1);
    scheduler_submit(&s, 1, "a");
    scheduler_submit(&s, 1, "b");

    int id;
    assert(scheduler_run_next(&s, &id) == 1);
    assert(scheduler_run_next(&s, &id) == 0);
}

static void test_submit_and_run_now_rejected_when_at_capacity(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_set_max_concurrent(&s, 1);
    int id;
    assert(scheduler_run_next(&s, &id) == 0); /* nothing pending yet, but exercise the cap machinery */
    int first = scheduler_submit_and_run_now(&s, 1, "urgent-1");
    assert(first >= 0);

    int second = scheduler_submit_and_run_now(&s, 1, "urgent-2");
    assert(second == -1);
}

int main(void) {
    test_run_next_rejected_when_at_capacity();
    test_submit_and_run_now_rejected_when_at_capacity();
    printf("PASS\n");
    return 0;
}

