#pragma once

#include "job.h"
#include "queue.h"

#define SCHEDULER_MAX_RUNNING 256
#define SCHEDULER_MAX_HISTORY 256
#define SCHEDULER_UNLIMITED -1

typedef struct {
    JobQueue pending;
    Job running[SCHEDULER_MAX_RUNNING];
    int running_count;
    Job history[SCHEDULER_MAX_HISTORY];
    int history_count;
    int max_concurrent; /* SCHEDULER_UNLIMITED, or a cap on running_count */
} Scheduler;

void scheduler_init(Scheduler *s);
void scheduler_set_max_concurrent(Scheduler *s, int max_concurrent);
int scheduler_submit(Scheduler *s, int priority, const char *payload);

/* Moves the highest-priority pending job to RUNNING; returns 1 on
 * success, 0 if nothing is pending OR max_concurrent is already
 * reached. */
int scheduler_run_next(Scheduler *s, int *out_id);

/* Submits AND immediately starts running a job (bypassing the normal
 * pending queue entirely) - e.g. an urgent out-of-band job. Must ALSO
 * respect max_concurrent: returns -1 if the cap is already reached
 * (nothing submitted), else the new job's id. */
int scheduler_submit_and_run_now(Scheduler *s, int priority, const char *payload);

int scheduler_complete(Scheduler *s, int id);
int scheduler_fail(Scheduler *s, int id);
int scheduler_find_state(const Scheduler *s, int id, JobState *out_state);

